document.addEventListener("DOMContentLoaded", function () {
    const secondLevelLinks = document.querySelectorAll('.menu-second-level a');
    const thirdLevelMenus = document.querySelectorAll('.menu-third-level-content');
    const blogContents = document.querySelectorAll('.blog-content');
    const menuFirstLevelLinks = document.querySelectorAll('.menu-first-level > li > a');

    // Add hover event for second-level links
    secondLevelLinks.forEach(link => {
        link.addEventListener('mouseenter', function () {
            const target = this.getAttribute('data-target');

            // Hide all third-level menus
            thirdLevelMenus.forEach(menu => {
                menu.style.display = 'none';
            });

            // Hide all blog contents
            blogContents.forEach(blog => {
                blog.style.display = 'none';
            });

            // Show the targeted third-level menu
            const thirdLevelMenu = document.getElementById(target);
            if (thirdLevelMenu) {
                thirdLevelMenu.style.display = 'block';
            }

            // Show the targeted blog content dynamically
            const blogContent = document.getElementById(target + '-blog');
            if (blogContent) {
                blogContent.style.display = 'block';
            }
        });
    });

    // Highlight the active first-level menu item
    const currentUrl = window.location.href;
    menuFirstLevelLinks.forEach(link => {
        if (link.href === currentUrl) {
            link.style.color = '#1426C5'; // Set text color to blue
            link.style.borderBottom = '2px solid #1426C5'; // Add bottom border
        }
    });

    // Highlight the active second-level and third-level menu items
    secondLevelLinks.forEach(link => {
        if (link.href === currentUrl) {
            link.style.color = 'blue'; // Set text color to blue
            const target = link.getAttribute('data-target');

            // Show the corresponding third-level menu
            const thirdLevelMenu = document.getElementById(target);
            if (thirdLevelMenu) {
                thirdLevelMenu.style.display = 'block';
            }

            // Show the corresponding blog content
            const blogContent = document.getElementById(target + '-blog');
            if (blogContent) {
                blogContent.style.display = 'block';
            }
        }
    });
});
